FATAL_TARGETS = {"/", "/*", "~", "~/", "*", ".", "..", HOME, HOME + "/"}


def unsafe_rm_target(arg: str) -> bool:
    """True if a recursive delete of `arg` would escape ~/code."""
    if arg in FATAL_TARGETS:
        return True
    expanded = os.path.expanduser(os.path.expandvars(arg))
    if not os.path.isabs(expanded):
        return False                      # relative paths: cwd is the agent's own tree
    real = os.path.normpath(expanded)
    return not (real == SANDBOX or real.startswith(SANDBOX + os.sep))
